import jakarta.validation.Valid;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthService authService;

    public AuthController(AuthService authService) {
        this.authService = authService;
    }

    @PostMapping("/register")
    public AuthResponse register(@Valid @RequestBody RegisterRequest request) {
        return authService.register(request);
    }

    @PostMapping("/login")
    public AuthResponse login(@Valid @RequestBody LoginRequest request) {
        return authService.login(request);
    }

    /** 登录态校验：SecurityConfig 已拦截匿名访问，principal 为 null 仅作兜底。 */
    @GetMapping("/me")
    public UserInfo me(@AuthenticationPrincipal AuthUser authUser) {
        if (authUser == null) {
            throw new BusinessException(401, "未登录或登录已过期");
        }
        return authService.getMe(authUser.getId());
    }
}

import { useCallback, useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from '../store/AuthContext'

/**
 * 阶段2 点赞/收藏交互：仅 UI 状态回显 + 未登录引导登录，不写库（写库属里程碑 4）。
 * 返回的 like/favorite 供详情页与播放页共用。
 */
export function useDramaInteractions() {
  const { user } = useAuth()
  const navigate = useNavigate()
  const [hint, setHint] = useState('')

  useEffect(() => {
    if (!hint) {
      return
    }
    const timer = setTimeout(() => setHint(''), 2500)
    return () => clearTimeout(timer)
  }, [hint])

  const guarded = useCallback(
    (message: string) => {
      if (!user) {
        const from = encodeURIComponent(window.location.pathname + window.location.search)
        navigate(`/login?from=${from}`)
        return
      }
      setHint(message)
    },
    [user, navigate],
  )

  const like = useCallback(() => guarded('点赞功能即将上线，敬请期待'), [guarded])
  const favorite = useCallback(() => guarded('收藏功能即将上线，敬请期待'), [guarded])

  return { like, favorite, hint }
}

