                }`}
              >
                {item}
              </button>
            ))}
          </nav>

          {visible.length === 0 ? (
            <p className="py-20 text-center text-sm text-neutral-400">
              {debouncedKeyword ? '没有找到相关短剧' : '该分类暂无短剧'}
            </p>
          ) : (
            <div className="grid grid-cols-2 gap-3 md:grid-cols-4 xl:grid-cols-6">
              {visible.map((drama) => (
