  const btn = document.querySelector('button[aria-label="清空搜索"]')
  if (!input || !btn) return { found: false }
  const ir = input.getBoundingClientRect()
  const br = btn.getBoundingClientRect()
  const cx = br.left + br.width / 2, cy = br.top + br.height / 2
  const hit = document.elementFromPoint(cx, cy)
  return {
    found: true,
    input: { w: ir.width, h: ir.height },
    btn: { x: br.left, y: br.top, w: br.width, h: br.height },
    hitTarget: hit ? hit.tagName + '.' + (hit.getAttribute('aria-label') ?? '') : 'null',
    btnComputedStyle: { display: getComputedStyle(btn).display, pointerEvents: getComputedStyle(btn).pointerEvents },
  }
})
state;

