@RestController
@RequestMapping("/api")
public class DramaController {

    private final DramaService dramaService;

    public DramaController(DramaService dramaService) {
        this.dramaService = dramaService;
    }

    /** C 端首页推荐流：上架短剧，点赞数倒序；keyword 非空时标题模糊搜索（PL-06），无参行为与阶段2一致。 */
