const browserPluginRoot =
  process.env.ZCODE_PLUGIN_ROOT ?? process.env.CLAUDE_PLUGIN_ROOT;
const { join } = await import("node:path");
const { pathToFileURL } = await import("node:url");
const browserClientUrl = pathToFileURL(
  join(browserPluginRoot, "scripts", "browser-client.mjs"),
).href;
const { setupBrowserRuntime } = await import(browserClientUrl);
await setupBrowserRuntime({ globals: globalThis });

const browser = await agent.browsers.get("iab");
// 复用已开的标签页切到主路径 3000
const match = (await browser.tabs.list()).find(t => (t.url ?? "").includes("localhost:3002"));
const tab = match ? await browser.tabs.get(match.id) : await browser.tabs.new();
await tab.goto("http://localhost:3000/");
await tab.playwright.waitForLoadState({ state: "domcontentloaded" });
await tab.playwright.waitForTimeout(1200);
const home = await tab.playwright.evaluate(() => ({
  headings: document.querySelectorAll("h2").length,
  search: !!document.querySelector('input[aria-label="搜索短剧"]'),
  mine: !!document.querySelector('a[href="/mine"]'),
}));
await tab.goto("http://localhost:3000/drama/1/play");
await tab.playwright.waitForLoadState({ state: "domcontentloaded" });
await tab.playwright.waitForTimeout(1500);
const play = await tab.playwright.evaluate(() => {
  const v = document.querySelector("video");
  const tip = [...document.querySelectorAll("p")].find(el => (el.textContent ?? "").includes("续播"));
  return { url: location.href, playing: v ? !v.paused && !v.ended : null, resumeTip: tip ? tip.textContent : null };
});
await tab.playwright.evaluate(() => { const v = document.querySelector("video"); if (v) v.pause(); });
nodeRepl.write(JSON.stringify({ home3000: home, play3000: play }));
